class Solution {
    public List<String> ambiguousCoordinates(String s) {
        String digits = s.substring(1, s.length() - 1);
        List<String> res = new ArrayList<>();
        int n = digits.length();
        for (int i = 1; i < n; i++) {
            List<String> left = makeNumbers(digits.substring(0, i));
            List<String> right = makeNumbers(digits.substring(i));
            for (String l : left) {
                for (String r : right) {
                    res.add("(" + l + ", " + r + ")");
                }
            }
        }
        return res;
    }

    private List<String> makeNumbers(String s) {
        List<String> res = new ArrayList<>();
        int len = s.length();
        // no decimal point
        if (isValidInteger(s)) res.add(s);
        // with decimal point
        for (int i = 1; i < len; i++) {
            String intPart = s.substring(0, i);
            String fracPart = s.substring(i);
            if (isValidInteger(intPart) && isValidFraction(fracPart)) {
                res.add(intPart + "." + fracPart);
            }
        }
        return res;
    }

    private boolean isValidInteger(String s) {
        if (s.length() > 1 && s.charAt(0) == '0') return false;
        return true;
    }

    private boolean isValidFraction(String s) {
        if (s.charAt(s.length() - 1) == '0') return false;
        return true;
    }
}
