class Solution {
    int[] parent, size;
    int[] dr = {-1,1,0,0};
    int[] dc = {0,0,-1,1};
    int m, n;

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        size[ra] += size[rb];
    }

    public int[] hitBricks(int[][] grid, int[][] hits) {
        m = grid.length;
        n = grid[0].length;
        int top = m * n;
        parent = new int[m * n + 1];
        size = new int[m * n + 1];
        for (int i = 0; i <= m * n; i++) { parent[i] = i; size[i] = 1; }

        int[][] g = new int[m][n];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                g[i][j] = grid[i][j];

        // remove hit bricks
        for (int[] h : hits) {
            g[h[0]][h[1]] = 0;
        }

        // build union find on remaining grid
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (g[i][j] == 1) {
                    int id = i * n + j;
                    if (i == 0) union(id, top);
                    for (int d = 0; d < 4; d++) {
                        int ni = i + dr[d], nj = j + dc[d];
                        if (ni >= 0 && ni < m && nj >= 0 && nj < n && g[ni][nj] == 1) {
                            union(id, ni * n + nj);
                        }
                    }
                }
            }
        }

        int[] result = new int[hits.length];
        for (int k = hits.length - 1; k >= 0; k--) {
            int r = hits[k][0], c = hits[k][1];
            if (grid[r][c] == 0) {
                result[k] = 0;
                continue;
            }
            int before = size[find(top)];
            int id = r * n + c;
            g[r][c] = 1;
            if (r == 0) union(id, top);
            for (int d = 0; d < 4; d++) {
                int ni = r + dr[d], nj = c + dc[d];
                if (ni >= 0 && ni < m && nj >= 0 && nj < n && g[ni][nj] == 1) {
                    union(id, ni * n + nj);
                }
            }
            int after = size[find(top)];
            result[k] = Math.max(0, after - before - 1);
        }

        return result;
    }
}
