import java.util.*;

class Solution {
    public int numFactoredBinaryTrees(int[] arr) {
        int MOD = 1000000007;
        Arrays.sort(arr);
        int n = arr.length;
        Map<Integer, Integer> index = new HashMap<>();
        for (int i = 0; i < n; i++) index.put(arr[i], i);
        long[] dp = new long[n];
        for (int i = 0; i < n; i++) {
            dp[i] = 1;
            for (int j = 0; j < i; j++) {
                if (arr[i] % arr[j] == 0) {
                    int other = arr[i] / arr[j];
                    if (index.containsKey(other)) {
                        dp[i] = (dp[i] + dp[j] * dp[index.get(other)]) % MOD;
                    }
                }
            }
        }
        long ans = 0;
        for (long d : dp) ans = (ans + d) % MOD;
        return (int) ans;
    }
}
