class Solution {
    public int clumsy(int n) {
        java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
        stack.push(n);
        int op = 0;
        for (int i = n - 1; i > 0; i--) {
            if (op == 0) {
                stack.push(stack.pop() * i);
            } else if (op == 1) {
                stack.push(stack.pop() / i);
            } else if (op == 2) {
                stack.push(i);
            } else {
                stack.push(-i);
            }
            op = (op + 1) % 4;
        }
        int sum = 0;
        while (!stack.isEmpty()) sum += stack.pop();
        return sum;
    }
}
