    private int[] stack;
    private int[] inc;
    private int size;
    private int maxSize;

    public CustomStack(int maxSize) {
        this.maxSize = maxSize;
        stack = new int[maxSize];
        inc = new int[maxSize];
        size = 0;
    }

    public void push(int x) {
        if (size < maxSize) {
            stack[size++] = x;
        }
    }

    public int pop() {
        if (size == 0) return -1;
        size--;
        int res = stack[size] + inc[size];
        if (size > 0) {
            inc[size - 1] += inc[size];
        }
        inc[size] = 0;
        return res;
    }

    public void increment(int k, int val) {
        int idx = Math.min(k, size) - 1;
        if (idx >= 0) {
            inc[idx] += val;
        }
    }
