    public int maxEqualFreq(int[] nums) {
        int[] count = new int[100001];
        int[] freq = new int[100001];
        int maxFreq = 0;
        int ans = 0;
        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];
            if (count[x] > 0) freq[count[x]]--;
            count[x]++;
            freq[count[x]]++;
            maxFreq = Math.max(maxFreq, count[x]);

            int len = i + 1;
            // case 1: all have freq maxFreq except one with freq 1
            if (maxFreq == 1) {
