            } else if (freq[maxFreq] * maxFreq + 1 == len && freq[1] == 1) {
                ans = len;
            } else if ((maxFreq - 1) * freq[maxFreq - 1] + maxFreq == len && freq[maxFreq] == 1) {
                ans = len;
            }
        }
        return ans;
    }
