    private boolean dfs(int node, int[][] graph, int[] state) {
        if (state[node] != 0) return state[node] == 2;
        state[node] = 1;
        for (int next : graph[node]) {
            if (!dfs(next, graph, state)) return false;
        }
        state[node] = 2;
        return true;
    }
}
