    public long maxRunTime(int n, int[] batteries) {
        long total = 0;
        for (int b : batteries) total += b;
        long lo = 1, hi = total / n, ans = 0;
        while (lo <= hi) {
            long mid = lo + (hi - lo) / 2;
            long sum = 0;
            for (int b : batteries) {
                sum += Math.min((long) b, mid);
            }
            if (sum >= mid * n) {
                ans = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return ans;
    }
