class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int sum = 0;
        for (int n : nums) sum += n;
        if (sum % k != 0) return false;
        int target = sum / k;
        java.util.Arrays.sort(nums);
        int n = nums.length;
        if (nums[n - 1] > target) return false;
        boolean[] used = new boolean[n];
        return backtrack(nums, used, k, 0, 0, target, n - 1);
    }

    private boolean backtrack(int[] nums, boolean[] used, int k, int start, int curr, int target, int startIdx) {
        if (k == 0) return true;
        if (curr == target) {
            return backtrack(nums, used, k - 1, 0, 0, target, nums.length - 1);
        }
        for (int i = startIdx; i >= 0; i--) {
            if (used[i] || curr + nums[i] > target) continue;
            used[i] = true;
            if (backtrack(nums, used, k, 0, curr + nums[i], target, i - 1)) return true;
