    int[] parent;
    int find(int x){ return parent[x]==x?x:(parent[x]=find(parent[x])); }
    void union(int a,int b){ parent[find(a)]=find(b); }
    public int regionsBySlashes(String[] grid) {
        int n = grid.length;
        parent = new int[4*n*n];
        for(int i=0;i<parent.length;i++) parent[i]=i;
        for(int r=0;r<n;r++){
            for(int c=0;c<n;c++){
                int base = 4*(r*n+c);
                char ch = grid[r].charAt(c);
                if(ch==' '){
                    union(base+0,base+1);
                    union(base+1,base+2);
                    union(base+2,base+3);
                } else if(ch=='/'){
                    union(base+0,base+3);
                    union(base+1,base+2);
                } else {
                    union(base+0,base+1);
                    union(base+2,base+3);
                }
                if(c+1<n){
                    int right=4*(r*n+c+1);
                    union(base+1,right+3);
                }
                if(r+1<n){
                    int down=4*((r+1)*n+c);
                    union(base+2,down+0);
                }
            }
        }
        int count=0;
        for(int i=0;i<parent.length;i++) if(find(i)==i) count++;
