        if (f - 1 > n - s) {
            int nf = n + 1 - s;
            int ns = n + 1 - f;
            f = nf; s = ns;
        }
        String key = n + "," + f + "," + s;
        if (memo.containsKey(key)) return memo.get(key);

        if (f + s == n + 1) {
            int[] res = new int[]{1, 1};
            memo.put(key, res);
            return res;
