class Solution {
    public String strWithout3a3b(int a, int b) {
        StringBuilder sb = new StringBuilder();
        while (a > 0 || b > 0) {
            boolean writeA;
            int n = sb.length();
            if (n >= 2 && sb.charAt(n-1) == 'a' && sb.charAt(n-2) == 'a') {
                writeA = false;
            } else if (n >= 2 && sb.charAt(n-1) == 'b' && sb.charAt(n-2) == 'b') {
                writeA = true;
            } else {
                writeA = a >= b;
            }
            if (writeA && a > 0) {
                sb.append('a');
                a--;
            } else if (!writeA && b > 0) {
                sb.append('b');
                b--;
            } else if (a > 0) {
                sb.append('a');
                a--;
            } else {
                sb.append('b');
                b--;
            }
        }
        return sb.toString();
    }
}
